-- RC34: mission evidence authorization must support both single-guard and multi-guard runtimes.
-- This closes two E2E gaps: real Guards were blocked by a developer-only storage authorizer,
-- and multi-guard slots were incorrectly validated against the single mission_engine_state.

create or replace function public.can_upload_developer_mission_evidence_rc1(p_object_name text)
returns boolean language plpgsql stable security definer set search_path=public set row_security=off as $$
declare parts text[];jid uuid;gid uuid;cp integer;begin
 parts:=storage.foldername(p_object_name);if array_length(parts,1)<3 then return false;end if;
 jid:=parts[1]::uuid;gid:=parts[2]::uuid;cp:=parts[3]::integer;
 if public.current_role()='platform_admin'::public.app_role then
  return exists(select 1 from public.marketplace_jobs j where j.id=jid and coalesce(j.pricing_snapshot->>'developer_test','false')='true' and ((greatest(1,coalesce(j.required_guards,1))=1 and exists(select 1 from public.job_assignments a join public.mission_engine_state s on s.job_id=a.job_id where a.job_id=jid and a.guard_id=gid and s.guard_id=gid and s.state in('active','checkpoint') and s.checkpoint_index=cp)) or (greatest(1,coalesce(j.required_guards,1))>1 and exists(select 1 from public.job_guard_slots gs join public.guard_slot_mission_state ss on ss.slot_id=gs.id where gs.job_id=jid and gs.guard_id=gid and ss.guard_id=gid and ss.state in('active','checkpoint') and ss.checkpoint_index=cp))));
 end if;
 return exists(select 1 from public.guards g where g.id=gid and g.user_id=auth.uid() and g.agency_approved=true) and exists(select 1 from public.marketplace_jobs j where j.id=jid and ((greatest(1,coalesce(j.required_guards,1))=1 and exists(select 1 from public.job_assignments a join public.mission_engine_state s on s.job_id=a.job_id where a.job_id=jid and a.guard_id=gid and s.guard_id=gid and s.state in('active','checkpoint') and s.checkpoint_index=cp)) or (greatest(1,coalesce(j.required_guards,1))>1 and exists(select 1 from public.job_guard_slots gs join public.guard_slot_mission_state ss on ss.slot_id=gs.id where gs.job_id=jid and gs.guard_id=gid and ss.guard_id=gid and ss.state in('active','checkpoint') and ss.checkpoint_index=cp))));
exception when others then return false;end $$;

-- Shared validation helpers keep the four public upload/register RPCs on the same runtime contract.
create or replace function public.guard_mission_evidence_runtime_ok_rc1(p_guard_id uuid,p_job_id uuid,p_checkpoint integer)
returns boolean language sql stable security definer set search_path=public set row_security=off as $$
 select exists(select 1 from public.marketplace_jobs j where j.id=p_job_id and ((greatest(1,coalesce(j.required_guards,1))=1 and exists(select 1 from public.job_assignments a join public.mission_engine_state s on s.job_id=a.job_id where a.job_id=p_job_id and a.guard_id=p_guard_id and s.guard_id=p_guard_id and s.state in('active','checkpoint') and s.checkpoint_index=p_checkpoint)) or (greatest(1,coalesce(j.required_guards,1))>1 and exists(select 1 from public.job_guard_slots gs join public.guard_slot_mission_state ss on ss.slot_id=gs.id where gs.job_id=p_job_id and gs.guard_id=p_guard_id and ss.guard_id=p_guard_id and ss.state in('active','checkpoint') and ss.checkpoint_index=p_checkpoint))));
$$;

create or replace function public.get_developer_guard_evidence_upload_rc1(p_guard_id uuid,p_job_id uuid,p_checkpoint integer,p_filename text,p_mime_type text,p_file_size bigint) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare ext text;path text;token uuid:=gen_random_uuid();max_size bigint;begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED';end if;if coalesce((select pricing_snapshot->>'developer_test' from public.marketplace_jobs where id=p_job_id),'false')<>'true' then raise exception 'DEVELOPER_TEST_JOB_REQUIRED';end if;if not public.guard_mission_evidence_runtime_ok_rc1(p_guard_id,p_job_id,p_checkpoint) then raise exception 'MISSION_NOT_ACCEPTING_EVIDENCE';end if;if p_mime_type not in('image/jpeg','image/png','image/webp','image/heic','image/heif','video/mp4','video/quicktime','video/webm') then raise exception 'INVALID_EVIDENCE_TYPE';end if;max_size:=case when p_mime_type like 'video/%' then 52428800 else 12582912 end;if p_file_size<=0 or p_file_size>max_size then raise exception 'INVALID_EVIDENCE_SIZE';end if;ext:=case p_mime_type when 'image/png' then 'png' when 'image/webp' then 'webp' when 'image/heic' then 'heic' when 'image/heif' then 'heif' when 'video/quicktime' then 'mov' when 'video/webm' then 'webm' when 'video/mp4' then 'mp4' else 'jpg' end;path:=p_job_id::text||'/'||p_guard_id::text||'/'||p_checkpoint::text||'/'||token::text||'.'||ext;return jsonb_build_object('bucket','mission-evidence','path',path);end $$;

create or replace function public.register_developer_guard_evidence_rc1(p_guard_id uuid,p_job_id uuid,p_checkpoint integer,p_storage_path text,p_mime_type text,p_file_size bigint,p_latitude double precision default null,p_longitude double precision default null) returns public.mission_evidence_media language plpgsql security definer set search_path=public set row_security=off as $$ declare m public.mission_evidence_media;max_size bigint;begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED';end if;if coalesce((select pricing_snapshot->>'developer_test' from public.marketplace_jobs where id=p_job_id),'false')<>'true' then raise exception 'DEVELOPER_TEST_JOB_REQUIRED';end if;if not public.guard_mission_evidence_runtime_ok_rc1(p_guard_id,p_job_id,p_checkpoint) then raise exception 'MISSION_NOT_ACCEPTING_EVIDENCE';end if;if p_checkpoint<0 or p_checkpoint>5 then raise exception 'CHECKPOINT_STATE_CONFLICT';end if;if p_storage_path !~ ('^'||p_job_id::text||'/'||p_guard_id::text||'/'||p_checkpoint::text||'/[A-Za-z0-9._-]+$') then raise exception 'INVALID_EVIDENCE_PATH';end if;if p_mime_type not in('image/jpeg','image/png','image/webp','image/heic','image/heif','video/mp4','video/quicktime','video/webm') then raise exception 'INVALID_EVIDENCE_TYPE';end if;max_size:=case when p_mime_type like 'video/%' then 52428800 else 12582912 end;if p_file_size<=0 or p_file_size>max_size then raise exception 'INVALID_EVIDENCE_SIZE';end if;insert into public.mission_evidence_media(job_id,guard_id,checkpoint_index,kind,storage_path,mime_type,file_size,latitude,longitude) values(p_job_id,p_guard_id,p_checkpoint,case when p_mime_type like 'video/%' then 'video' else 'photo' end,p_storage_path,p_mime_type,p_file_size,p_latitude,p_longitude) returning * into m;return m;end $$;

create or replace function public.get_guard_evidence_upload_rc1(p_job_id uuid,p_checkpoint integer,p_mime_type text,p_file_size bigint) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare g public.guards;ext text;path text;token uuid:=gen_random_uuid();max_size bigint;begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;select * into g from public.guards where user_id=auth.uid() and agency_approved=true limit 1;if g.id is null then raise exception 'GUARD_REQUIRED';end if;if not public.guard_mission_evidence_runtime_ok_rc1(g.id,p_job_id,p_checkpoint) then raise exception 'MISSION_NOT_ACCEPTING_EVIDENCE';end if;if p_mime_type not in('image/jpeg','image/png','image/webp','image/heic','image/heif','video/mp4','video/quicktime','video/webm') then raise exception 'INVALID_EVIDENCE_TYPE';end if;max_size:=case when p_mime_type like 'video/%' then 52428800 else 12582912 end;if p_file_size<=0 or p_file_size>max_size then raise exception 'INVALID_EVIDENCE_SIZE';end if;ext:=case p_mime_type when 'image/png' then 'png' when 'image/webp' then 'webp' when 'image/heic' then 'heic' when 'image/heif' then 'heif' when 'video/quicktime' then 'mov' when 'video/webm' then 'webm' when 'video/mp4' then 'mp4' else 'jpg' end;path:=p_job_id::text||'/'||g.id::text||'/'||p_checkpoint::text||'/'||token::text||'.'||ext;return jsonb_build_object('bucket','mission-evidence','path',path,'guard_id',g.id);end $$;

create or replace function public.register_guard_evidence_rc1(p_job_id uuid,p_checkpoint integer,p_storage_path text,p_mime_type text,p_file_size bigint,p_latitude double precision default null,p_longitude double precision default null) returns public.mission_evidence_media language plpgsql security definer set search_path=public set row_security=off as $$ declare g public.guards;m public.mission_evidence_media;max_size bigint;begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;select * into g from public.guards where user_id=auth.uid() and agency_approved=true limit 1;if g.id is null then raise exception 'GUARD_REQUIRED';end if;if not public.guard_mission_evidence_runtime_ok_rc1(g.id,p_job_id,p_checkpoint) then raise exception 'MISSION_NOT_ACCEPTING_EVIDENCE';end if;if p_checkpoint<0 or p_checkpoint>5 then raise exception 'CHECKPOINT_STATE_CONFLICT';end if;if p_storage_path !~ ('^'||p_job_id::text||'/'||g.id::text||'/'||p_checkpoint::text||'/[A-Za-z0-9._-]+$') then raise exception 'INVALID_EVIDENCE_PATH';end if;if p_mime_type not in('image/jpeg','image/png','image/webp','image/heic','image/heif','video/mp4','video/quicktime','video/webm') then raise exception 'INVALID_EVIDENCE_TYPE';end if;max_size:=case when p_mime_type like 'video/%' then 52428800 else 12582912 end;if p_file_size<=0 or p_file_size>max_size then raise exception 'INVALID_EVIDENCE_SIZE';end if;insert into public.mission_evidence_media(job_id,guard_id,checkpoint_index,kind,storage_path,mime_type,file_size,latitude,longitude) values(p_job_id,g.id,p_checkpoint,case when p_mime_type like 'video/%' then 'video' else 'photo' end,p_storage_path,p_mime_type,p_file_size,p_latitude,p_longitude) returning * into m;return m;end $$;
